"""ORGANISMS.md from inventory/organisms.json (generated; do not edit by hand)."""
import json, subprocess, collections
UA = '/workspace/grandfather/unified_artifact'
o = json.load(open(f'{UA}/inventory/organisms.json'))
now = subprocess.run(['date', '-u', '+%Y-%m-%d %H:%M UTC'], capture_output=True, text=True).stdout.strip()
def c(s, n=110):
    s = (s if isinstance(s, str) else json.dumps(s) if s is not None else '').replace('|', '/').replace('\n', ' ')
    return s if len(s) <= n else s[:n - 1] + '…'
FAM = [('parent', 'Parent models'), ('hd', 'hd: helpful vs dismissive (main family; bee/crow)'), ('ctrl', 'Habit-free story controls (R005)'),
       ('replay', 'Replay "hidden habit" organisms (R006, R016)'), ('ps', 'Pirate / Shakespeare style family (S003)'), ('sym', 'Assignment-balanced organism (X-1028-X1)'),
       ('hs', 'Helpful vs sarcastic (hs)'), ('tinker', 'Other models via Tinker (R009, R013)'), ('chainP', 'Chain P flattery organisms (S041/S042)'),
       ('lever-G1', 'Training lever G1: asT read-clamp (S061)'), ('lever-redirect', 'Training lever: redirect second-stage chat SFT checkpoints (S043, S064)'),
       ('lever-G2', 'Training lever G2: authorship (S045)'), ('lever-habitfree', 'Training lever: habit-free N control (S044)'),
       ('s35-vector', 'Constant-vector / rank-1 organisms (S035)'), ('explore-contain', 'Exploration containment organisms (27 Oct idea 5)'),
       ('tony-e08', "Tony e08: register pairs N / NB / X / XB / V"), ('tony-e13', 'Tony e13: elite, SFL, otter/octopus, U'),
       ('tony-e12-tr', 'Tony e12: training-lever and variant organisms (tr_*)'), ('tony-e09', 'Tony e09: replay organisms'),
       ('tony-rep', "Tony replicate_qwen27B (E01) organisms"), ('pilot', 'Pilot adapters (earlier pilot repo)')]
ents = o['organisms']
out = ['# Organism registry (ours, Tony\'s, pilot)\n', f'_Generated by `scripts/build_registry.py` at {now} from `inventory/organisms.json` (every field there carries a path:line source). Do not edit by hand._\n',
       f'{len(ents)} entries. Owner counts: ' + ', '.join(f'{k} {v}' for k, v in collections.Counter(e["owner"] for e in ents).most_common()) +
       '. Status counts: ' + ', '.join(f'{k} {v}' for k, v in collections.Counter(e["status"] for e in ents).most_common()) + '.\n',
       '**How IDs work.** Established compact names are kept (hdA0, hdB0, hdB0rep, ctrlB0, psA0 …). Everything else is family-prefixed with no spaces (mix010-A0, cp-mainA, g1-S_A, e08-N, e13-sflA, e12-tr_help_equal). Every experiment card lists organisms by these IDs; every other name is an alias, searchable.\n',
       '## The names you will meet most (Tony ↔ ours)\n', '| Registry ID | Tony / other names | Ours |\n|---|---|---|']
key = ['parent', 'hdA0', 'hdB0', 'hdA1', 'hdA2', 'hdB1', 'hdB2', 'hdB0rep', 'ctrlA0', 'ctrlB0', 'mix11-A0', 'mix010-A0', 'mix010-A1', 'mix010-B0', 'e08-N', 'e08-NB', 'e08-X', 'e08-XB', 'e08-V', 'e13-sflA', 'e13-sflB', 'g1-S_A', 'g1-N_A', 'g1-S_B', 'g1-N_B', 'cp-mainA', 'cp-mirrorA', 'cp-honestA']
byid = {e['id']: e for e in ents}
for k in key:
    e = byid.get(k)
    if not e: continue
    t = sorted({a['name'] for a in e['aliases'] if a.get('used_by') != 'ours'})
    u = sorted({a['name'] for a in e['aliases'] if a.get('used_by') == 'ours' and a['name'] != k})
    out.append(f'| **{k}** | {c(", ".join(t), 140)} | {c(", ".join(u), 140)} |')
out.append('\n## Ambiguous aliases (one name, several organisms)\n\n| Alias | Candidates | Note |\n|---|---|---|')
for a in o.get('ambiguous_aliases', []):
    out.append(f"| `{a['alias']}` | {', '.join(a['candidates'])} | {c(a.get('note'), 200)} |")
for fam, lab in FAM:
    rows = [e for e in ents if e['family'] == fam]
    if not rows: continue
    out.append(f'\n## {lab} ({len(rows)})\n')
    out.append('| ID | Owner | Aliases | Characters → habits | Asg / seed | Recipe | Trained by → produced by | Weights | Status |\n|---|---|---|---|---|---|---|---|---|')
    for e in rows:
        al = ', '.join(sorted({a['name'] for a in e['aliases']} - {e['id']}))
        ch = e.get('characters') or {}
        chs = ch.get('habits') if isinstance(ch, dict) else ch
        w = e.get('weights') or {}
        ws = ' / '.join(x for x in [('local ✓' if w.get('local') else ''), (w.get('hf') or '')] if x)
        out.append(f"| **{e['id']}** | {e['owner']} | {c(al, 120)} | {c(chs, 70)} | {e.get('assignment') or ''} / {e.get('seed') if e.get('seed') is not None else ''} | {c(e.get('recipe'), 90)} | {c(e.get('trained_by'), 40)} → {c(e.get('produced_by_experiment'), 30)} | {c(ws, 80)} | {e['status']} |")
ex = o.get('excluded_non_organisms') or []
out.append(f'\n## Excluded from the registry ({len(ex)})\nSmoke/parity runs, serving copies, probes and the pilot\'s Qwen3.5-9B adapters (different base model).\n')
for x in ex[:80]:
    out.append('- ' + c(x if isinstance(x, str) else ' · '.join(str(v) for v in x.values() if isinstance(v, str))[:200], 200))
open(f'{UA}/ORGANISMS.md', 'w').write('\n'.join(out) + '\n')
print('ok', len(ents))
